const FAQ_STOP=new Set("a o os as um uma uns umas de do da dos das em no na nos nas por para pelo pela com sem e ou que qual quais quando onde como quem e é sao são ser se ao aos meu minha seu sua posso pode podem ha há tem ter eu voces vocês the an of to in on at for with and or is are be do does can could i you we my your our what which when where how who there this that it from about please me any get find much many quanto quanta quantos quantas preciso quero gostaria saber need want know".split(" "));
const faqNorm=s=>String(s||"").toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g,"").replace(/[^a-z0-9]+/g," ").trim();
const faqTok=s=>faqNorm(s).split(" ").filter(w=>w.length>1&&!FAQ_STOP.has(w));
function faqSim(a,b){if(a===b)return 1;const m=Math.min(a.length,b.length);if(m<3)return 0;if(m>=4&&(a.startsWith(b)||b.startsWith(a)))return .9;
  let k=0;while(k<m&&a[k]===b[k])k++;return k>=(m<=6?Math.max(4,m-1):Math.max(5,Math.ceil(m*.75)))?.8:0}
function faqMatch(items,text){const qt=[...new Set(faqTok(text))];if(!qt.length)return[];
  return items.map(it=>{const qw=faqTok([it.q&&it.q.en,it.q&&it.q.pt].join(" ")),kw=faqTok([it.kw&&it.kw.en,it.kw&&it.kw.pt].join(" ").replace(/,/g," "));
    let sc=0;qt.forEach(t=>{let b=0;qw.forEach(w=>{b=Math.max(b,faqSim(t,w))});kw.forEach(w=>{b=Math.max(b,faqSim(t,w)*1.15)});sc+=Math.min(1,b)});
    return{it,s:sc/Math.max(1,Math.min(qt.length,4))}}).filter(r=>r.s>=.34).sort((a,b)=>b.s-a.s)}

