/* vídeos do topo: um em loop, ou vários em sequência com transição cruzada */
const HV={key:"",list:[],i:0,cur:0,prep:-1,swapping:false,poster:"",paused:(()=>{try{return sessionStorage.getItem("cdm-hv-paused")==="1"}catch(e){return false}})()};
