function togglePause(){HV.paused=!HV.paused;try{sessionStorage.setItem("cdm-hv-paused",HV.paused?"1":"0")}catch(e){}
  const el=vEls()[HV.cur];if(el&&el.getAttribute("src")){if(HV.paused){vEls().forEach(v=>{try{v.pause()}catch(e){}})}else tryPlay(el)}syncPause()}
const vEls=()=>[$("#heroVideo"),$("#heroVideo2")];
function vidItems(M){const a=(M.videos||[]).map(v=>typeof v==="string"?{src:v}:(v||{})).filter(v=>v.src&&v.on!==false);if(!a.length&&M.video)a.push({src:M.video});return a}
