function closeMenu(){$("#hdr").classList.remove("open");$("#menuBtn").setAttribute("aria-expanded","false");document.querySelectorAll(".nav li.open").forEach(li=>{li.classList.remove("open");li.querySelector("button").setAttribute("aria-expanded","false")})}
