/* ---------- banner pop-up da página inicial (ocasiões especiais) ---------- */
let popTimer=null,popDone=false;
function popKey(P){const s=JSON.stringify([P.image,P.imageMobile,P.title,P.text,P.cta,P.start,P.end,P.recur==="yearly"?new Date().getFullYear():""]);let h=0;for(let i=0;i<s.length;i++)h=(h*31+s.charCodeAt(i))|0;return"cdm-pop-"+(h>>>0).toString(36)}
/* calendário anual: vários banners, cada um com as suas datas (uma vez ou todos os anos) */
function popList(){const P=data.popup||{};if(P.enabled===false)return[];
  if(Array.isArray(P.items)&&P.items.length)return P.items.filter(x=>x&&x.on!==false);
  return P.enabled&&(P.image||L(P.title)||L(P.text))?[Object.assign({recur:"once"},P)]:[]}
function popInRange(it,today){const md=today.slice(5),s=it.start||"",e=it.end||"";
  if(it.recur==="yearly"){const a=s?s.slice(5):"",b=e?e.slice(5):"";if(!a&&!b)return true;if(a&&!b)return md>=a;if(!a&&b)return md<=b;return a<=b?(md>=a&&md<=b):(md>=a||md<=b)}
  if(s&&today<s)return false;if(e&&today>e)return false;return true}
function popSpan(it){if(!it.start||!it.end)return 1e9;const d=(Date.parse(it.end)-Date.parse(it.start))/864e5;return d<0?d+365:d}
function popPick(){const today=new Date().toISOString().slice(0,10);
  return popList().filter(it=>(it.image||L(it.title)||L(it.text))&&popInRange(it,today)).map((it,k)=>({it,k,sp:popSpan(it)})).sort((a,b)=>a.sp-b.sp||a.k-b.k).map(x=>x.it)[0]||null}
function popActive(P){if(!P)return false;
  const k=popKey(P),f=P.freq||"session",today=new Date().toISOString().slice(0,10);
  try{if(f==="session"&&sessionStorage.getItem(k))return false;if(f==="once"&&localStorage.getItem(k))return false;if(f==="day"&&localStorage.getItem(k)===today)return false}catch(e){}
  return true}
function popRemember(P){const k=popKey(P),f=P.freq||"session",today=new Date().toISOString().slice(0,10);try{if(f==="session")sessionStorage.setItem(k,"1");else if(f==="once")localStorage.setItem(k,"1");else if(f==="day")localStorage.setItem(k,today)}catch(e){}}
function popCheck(slug){if(slug!=="home"){clearTimeout(popTimer);return}if(popDone||$("#pop"))return;const P=popPick();if(!P||!popActive(P))return;
  clearTimeout(popTimer);popTimer=setTimeout(()=>{if((route.split("~")[0]||"home")==="home"&&!$("#pop"))popShow(P)},Math.max(0,Math.min(30,+P.delay||0))*1000)}
function popShow(P,preview){popDone=true;if(!preview)popRemember(P);const mode=P.layout==="center"?"center":"card",ttl=L(P.title),txt=L(P.text),cta=L(P.cta);
  const href=P.url?safeUrl(P.url):(P.page&&(data.pages[P.page]||P.page==="home")?"#"+P.page:"");const ext=/^https?:/i.test(P.url||"");
  const img=P.image?`<picture class="pop-img">${P.imageMobile?`<source media="(max-width:600px)" srcset="${esc(P.imageMobile)}">`:""}<img src="${esc(P.image)}" alt="${esc(ttl||L(P.alt)||"")}" decoding="async"></picture>`:"";
  const body=ttl||txt||(cta&&href)?`<div class="pop-b">${ttl?`<h2 id="popT">${esc(ttl)}</h2>`:""}${txt?`<p>${esc(txt)}</p>`:""}${cta&&href?`<a class="btn btn-primary pop-cta" href="${esc(href)}"${ext?' target="_blank" rel="noopener noreferrer"':""}>${esc(cta)} ${arrow}</a>`:""}</div>`:"";
  const w=document.createElement("div");w.id="pop";w.className="pop "+mode+(body?"":" img-only")+((data.faq||{}).side==="left"?" right":"");
  w.innerHTML=`${mode==="center"?'<div class="pop-bd" data-popx></div>':""}<div class="pop-c" role="dialog" aria-modal="${mode==="center"}" ${ttl?'aria-labelledby="popT"':`aria-label="${esc(L(P.alt)||"Banner")}"`}>${href&&!body&&img?`<a href="${esc(href)}"${ext?' target="_blank" rel="noopener noreferrer"':""} data-popgo>${img}</a>`:img}${body}<button type="button" class="pop-x" data-popx aria-label="${esc(U("faqClose"))}"><svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" aria-hidden="true"><path d="M6 6l12 12M18 6 6 18"/></svg></button></div>`;
  document.body.appendChild(w);requestAnimationFrame(()=>requestAnimationFrame(()=>w.classList.add("in")));
  if(mode==="center"){popPrevFocus=document.activeElement;setTimeout(()=>{const x=w.querySelector(".pop-x");x&&x.focus({preventScroll:true})},50)}}
let popPrevFocus=null;
function popClose(){const w=$("#pop");if(!w)return;w.classList.remove("in");w.classList.add("out");setTimeout(()=>w.remove(),260);if(popPrevFocus&&popPrevFocus.focus){try{popPrevFocus.focus({preventScroll:true})}catch(e){}}popPrevFocus=null}
document.addEventListener("click",e=>{if(e.target.closest("[data-popx]")){popClose();return}if(e.target.closest("#pop .pop-cta,[data-popgo]"))popClose()});
document.addEventListener("keydown",e=>{if(e.key==="Escape"&&$("#pop"))popClose()});
(function(){let y0=null;document.addEventListener("touchstart",e=>{const c=e.target.closest&&e.target.closest("#pop.card .pop-c");y0=c?e.touches[0].clientY:null},{passive:true});
  document.addEventListener("touchend",e=>{if(y0==null)return;const dy=e.changedTouches[0].clientY-y0;y0=null;if(dy>60)popClose()},{passive:true})})();

